<template>
  <div id="checkout-container"></div>
</template>

<script>
import colors from "@/utils/colors.js";
import params from "@/utils/params.js";
import CheckoutMixins from "@/utils/checkout-mixins";
import cloneDeep from "lodash/cloneDeep";

export default {
  name: "EmbedWidget",
  mixins: [CheckoutMixins],
  props: {
    amount: 0,
    checkoutOptions: {
      type: Object,
      default: () => cloneDeep(params)
    }
  },
  beforeMount() {
    this.checkoutOptions.params.amount = this.amount * 100;
  },
  mounted() {
    this.checkout = window.checkout("#checkout-container", this.checkoutOptions);
    const that = this;
    this.checkout.$on('success', function(model) {
      that.paymentApproved()
    })
  },
  unmounted() {
    if (this.checkout) {
      this.checkout.$destroy();
      this.checkout.$el.remove();
    }
  },
  data() {
    return {
      colors: colors,
      checkout: null
    };
  },
};
</script>
