<template>
  <v-col class="mt-0 pt-0">
    <div class="d-flex justify-center">
      <v-btn
          :class="{ 'active-btn': mobile }"
          @click="mobile = true; tablet = false; this.initCheckout('#checkout-container-mobile')"
          size="large"
          variant="plain"
          icon="mdi-cellphone">
      </v-btn>
      <v-btn
          :class="{ 'active-btn': tablet }"
          @click="tablet = true; mobile = false; this.initCheckout('#checkout-container-tablet')"
          size="large"
          variant="plain"
          icon="mdi-tablet">

      </v-btn>
    </div>
    <div v-if="mobile" class="d-flex flex-row justify-center pa-md-10 position-relative pt-0">
      <v-img
          class="c-img"
          width="260"
          :src="mobile_frame">
      </v-img>
      <div class="c-content flitt-checkout" id="checkout-container-mobile"></div>
    </div>
    <div v-if="tablet" class="d-flex flex-row justify-center pa-md-10 position-relative pt-0">
      <v-img
          class="c-img-tablet"
          width="460"
          :src="tablet_frame">
      </v-img>
      <div class="c-content-tablet flitt-checkout" id="checkout-container-tablet"></div>
    </div>
  </v-col>
</template>

<script>
import colors from "@/utils/colors.js";
import params from "@/utils/params";

import mobile_frame from "@/assets/images/phone_frame.svg";
import tablet_frame from "@/assets/images/tablet.png";
import cloneDeep from "lodash/cloneDeep";


export default {
  name: "MobileWidget",
  props: {
    amount: 0,
    src: '',
    checkoutOptions: {
      type: Object,
      default: () => cloneDeep(params)
    }
  },
  methods: {
    initCheckout(container) {
      this.checkout = window.checkout(container, this.checkoutOptions);
    },
  },
  beforeMount() {
    this.checkoutOptions.params.amount = this.amount * 100;
  },
  mounted() {
    this.initCheckout("#checkout-container-mobile")
  },
  unmounted() {
    if (this.checkout) {
      this.checkout.$destroy();
      this.checkout.$el.remove();
    }
  },
  data() {
    return {
      mobile: true,
      tablet: false,
      mobile_frame: mobile_frame,
      tablet_frame: tablet_frame,
      colors: colors,
      checkout: null
    };
  },

};
</script>
<style>
.active-btn {
  opacity: 1;
}

.c-img {
  position: absolute;
  z-index: 0;
  top: 45px
}

.c-content {
  width: 100%;
  scale: 0.62;
  overflow: hidden;
  height: 100%
}

.c-content-tablet {
  width: 100%;
  scale: 0.92;
  overflow: hidden;
  height: 100%
}

.c-img-tablet {
  position: absolute;
  z-index: 0;
  top: 10px
}

@media screen and (max-width: 1024px) {
  .c-img {
    top: 15px
  }

  .c-content-tablet {
    scale: 0.75;
  }

  .c-content {
    scale: 0.63;
  }
}

@media screen and (max-width: 375px) {
  .c-content {
    scale: 0.79;
  }

  .c-img {
    top: 0
  }
}
</style>
