<template>
  <v-row align="center">
    <v-col sm="8" md="4" lg="3" class="d-flex flex-column pa-4 justify-center justify-lg-end ma-auto mr-md-0">
      <ProductList :d_total="false"></ProductList>
    </v-col>
    <v-col sm="12" md="8" lg="7" style="min-height: 500px; margin-top: 20px;" class="d-flex align-center justify-center justify-md-start">
      <EmbedWidget :checkoutOptions="checkoutOptions" :amount="amount"></EmbedWidget>
    </v-col>
  </v-row>
</template>
<script>
import EmbedWidget from "@/components/widgets/Embed.vue";
import ProductList from "@/components/products/ProductList.vue";
import colors from "@/utils/colors.js";
import params from "@/utils/params";
import cloneDeep from 'lodash/cloneDeep';

export default {
  name: "PlainCardWidget",
  components: {EmbedWidget, ProductList},
  props: {
    amount: 0,
    checkoutOptions: {
      type: Object,
      default: () => cloneDeep(params)
    }
  },
  beforeMount() {
    this.checkoutOptions.css_variable = {
      main: colors.primary,
    }
    this.checkoutOptions.options = {
      full_screen: false,
      theme: {
        layout: 'plain',
        type: "light",
        preset: "reset"
      },
      card_icons: [],
      show_amount: false,
      show_email: false,
      show_fee: false,
      show_lang: false,
      show_link: false,
      show_order_desc: false,
      show_pay_button_amount: false,
      show_secure_message: false,
      show_test_mode: false,
      show_title: false,
      loading:
          "data:image/svg+xml;base64,",
      logo_url:
          "data:image/svg+xml;base64,"
    }
  },
  data() {
    return {
      colors: colors
    };
  },
};
</script>
